def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def run(args,text=True): return subprocess.run(args,cwd=repo,text=text,capture_output=True)
def porcelain():
    p=run(['git','status','--porcelain=v1','-z','-uall'],text=False)
    if p.returncode: raise RuntimeError(p.stderr.decode(errors='replace'))
    recs=p.stdout.split(b'\0'); result={}; i=0
    while i<len(recs):
        rec=recs[i]; i+=1
        if not rec: continue
        s=rec.decode('utf-8','surrogateescape')
        if len(s)<4 or s[2]!=' ': raise RuntimeError(f'malformed porcelain record: {s!r}')
        st=s[:2]; path=s[3:]
        if st[0] in 'RC' or st[1] in 'RC':
            if i>=len(recs): raise RuntimeError('truncated rename/copy')
            i+=1
        result[path]=st
    return result
checks=[]
def add(name,ok,detail=''): checks.append({'check':name,'status':'PASS' if ok else 'FAIL','detail':detail})
head=run(['git','rev-parse','HEAD']).stdout.strip(); remote=run(['git','rev-parse','origin/main']).stdout.strip(); branch=run(['git','branch','--show-current']).stdout.strip()
add('head-lock',head==EXPECTED_HEAD,f'HEAD={head}'); add('origin-main-lock',remote==EXPECTED_HEAD,f'origin/main={remote}'); add('branch-main',branch=='main',f'branch={branch}')
try: actual=porcelain(); add('porcelain-parse',True,f'paths={len(actual)}')
except Exception as e: actual={}; add('porcelain-parse',False,str(e))
expected_paths=set(EXPECTED_PRIOR)|{TARGET,AUDIT_REL}
add('worktree-path-count',len(actual)==len(expected_paths),f'expected={len(expected_paths)} actual={len(actual)}')
add('worktree-path-set',set(actual)==expected_paths,f'missing={sorted(expected_paths-set(actual))} extra={sorted(set(actual)-expected_paths)}')
for rel,meta in EXPECTED_PRIOR.items():
    p=repo/rel; ok=p.is_file() and sha(p)==meta['sha256'] and actual.get(rel)==meta['status']
    add('prior-lock:'+rel,ok,f"expected_status={meta['status']} actual_status={actual.get(rel)}")
p=repo/TARGET; text=p.read_text(encoding='utf-8') if p.is_file() else ''
q=run(['git','show',f'HEAD:{TARGET}']); head_text=q.stdout if q.returncode==0 else ''
expected_text=head_text.replace(OLD,NEW,1) if head_text.count(OLD)==1 else None
add('target-status',actual.get(TARGET)==' M',f'actual={actual.get(TARGET)!r}')
add('target-post-sha',p.is_file() and sha(p)==EXPECTED_TARGET_SHA,f'expected={EXPECTED_TARGET_SHA} actual={sha(p) if p.is_file() else None}')
add('head-contained-old-phrase-once',q.returncode==0 and head_text.count(OLD)==1,f'head_old_occurrences={head_text.count(OLD)}')
add('old-phrase-absent',text.count(OLD)==0,f'current_old_occurrences={text.count(OLD)}')
add('new-phrase-delta-plus-one',text.count(NEW)==head_text.count(NEW)+1,f'head_new_occurrences={head_text.count(NEW)} current_new_occurrences={text.count(NEW)}')
add('exact-single-replacement',expected_text is not None and text==expected_text,'current target must equal HEAD with exactly one OLD→NEW replacement')
audit_path=repo/AUDIT_REL; add('audit-script-untracked',audit_path.is_file() and actual.get(AUDIT_REL)=='??',f'status={actual.get(AUDIT_REL)!r}')
d=run(['git','diff','--check']); add('git-diff-check',d.returncode==0,(d.stdout+d.stderr).strip())
fail=[c for c in checks if c['status']!='PASS']
with (out/'search-dominance-1e2c-r2c-checks.csv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=['check','status','detail']); w.writeheader(); w.writerows(checks)
res={'schema':'neuvago-search-dominance-1e2c-r2c-glossary-topic-layer-repair-audit-v2','status':'PASS' if not fail else 'FAIL','checks_total':len(checks),'checks_passed':len(checks)-len(fail),'failures':fail,'target':TARGET,'target_post_sha256':EXPECTED_TARGET_SHA,'head_new_occurrences':head_text.count(NEW),'current_new_occurrences':text.count(NEW),'scope_note':'Audit recovery only. The public glossary micro-repair remains one exact OLD→NEW replacement; no public source content is changed by this recovery.'}
(out/'SEARCH-DOMINANCE-1E2C-R2C-AUDIT.json').write_text(json.dumps(res,indent=2)+'\n'); print(json.dumps(res,indent=2)); sys.exit(1 if fail else 0)
